xinshengCustomCss:
/* 暗色科幻风 — 修改 CSS 变量快速换肤 */
.xt-root {
    --xt-bg: #0e1117;
    --xt-text: #e0e0e0;
    --xt-text-sub: #8888aa;
    --xt-text-muted: #555577;
    --xt-accent: #63b3ed;
    --xt-accent-bg: rgba(99,179,237,0.1);
    --xt-border: #2a2a44;
    --xt-radius: 20px;
    --xt-font: "Kaiti", "STKaiti", serif;
}
.xt-avatar { border-color: var(--xt-accent); }
.xt-section-body { border-left-width: 4px; font-size: 17px; }
.xt-grid-stat { background: rgba(255,255,255,0.04); }
.xt-bar-fill { background: linear-gradient(to right, #63b3ed, #b794f4); }
.xt-bubble-right .xt-bubble-body { background: #63b3ed; }
.xt-footer { color: #555577; }

xinshengLayout:
# 情侣卡片 — 双头像 + 条件渲染
@duo charImage charName userImage userName .fadeInDown
@badge bondDays "天" .scaleIn.delay200

@row 2
@card "TA的心声"
  @quote innerVoice .fadeInUp
@endcard
@card "此刻状态"
  @text statusText .fadeInUp
  @ring emotionLevel "情绪" .scaleIn.delay300
@endcard
@endrow

@if emotionLevel > 80
  @marquee secretHappy .shimmer
@endif

@tags .fadeIn.delay400
  mood
  weather
  "❤️"

@footer WITH YOU
